responsive='''@media(max-width:850px){.nav{align-items:flex-start;flex-direction:column;gap:14px}nav{gap:14px}.hero,.guide .hero,.split,.todo .hero,.expense .hero,.calendar-theme .hero,.tools .hero{grid-template-columns:1fr;gap:24px}.hero img,.guide .hero img,.stay .hero img{height:330px}.hero{margin-bottom:35px}.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.toolbar{grid-template-columns:1fr 1fr}.toolbar input{grid-column:1/-1}}@media(max-width:520px){main{padding:24px 18px 50px}.nav{padding:18px}.brand{font-size:21px}nav{gap:10px 16px}nav a{font-size:13px}.grid,.gallery .grid,.stats{grid-template-columns:1fr}.hero img{height:280px}h1{letter-spacing:-1px}.toolbar{grid-template-columns:1fr}.panel{padding:18px}.row{flex-wrap:wrap}.sectionhead{align-items:flex-start}.gallery .item img{height:260px}.day{font-size:13px;padding:10px 0}footer{padding:24px 18px}}'''

def page(c,title,body,active=''):
    slug,name,cat,headline,desc,kind,color,items,photo=c
    nav=[('index.html','Trang chủ'),('products.html','Khám phá' if kind not in ['shop','course'] else ('Sản phẩm' if kind=='shop' else 'Khóa học')),('about.html','Giới thiệu'),('contact.html','Liên hệ'),('feedback.html','Góp ý'),('login.html','Tài khoản')]
    links=''.join(f'<a href="{url}" '+('aria-current="page"' if url==active else '')+f'>{label}</a>' for url,label in nav)
    return f'''<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{desc}"><title>{title} · {name}</title><link rel="stylesheet" href="css/style.css"><link rel="stylesheet" href="css/responsive.css"><script defer src="js/data.js"></script><script defer src="js/main.js"></script></head><body class="{kind}" style="--accent:{color};--paper:{'#f1f4f2' if kind in ['booking','guide','course'] else '#f8f6f0'}"><a class="skip" href="#main">Đến nội dung</a><header><div class="nav"><a class="brand" href="index.html">{name}</a><nav aria-label="Điều hướng chính">{links}</nav></div></header><main id="main" class="fade">{body}<p id="status" class="message" role="status" aria-live="polite"></p></main><footer><div><span>{name} / {cat}</span><span>Đồ án COMP1802 · <a href="../index.html">Tất cả project</a> · <a href="change-password.html">Đổi mật khẩu</a> · <a href="manage.html">Thêm nội dung</a></span></div></footer></body></html>'''

def form(fields,action,label):
    return f'<form data-form="{action}">'+fields+f'<button>{label}</button></form>'
def inp(label,name,typ='text',extra=''):
    return f'<label>{label}<input name="{name}" type="{typ}" required {extra}></label>'
