    feedback='<div class="narrow"><h1>Góp ý</h1><p>Điều gì có thể làm tốt hơn trong lần cập nhật tới?</p>'+form(inp('Họ tên','name')+'<label>Đánh giá<select name="rating"><option value="5">5 — Rất hài lòng</option><option value="4">4 — Hài lòng</option><option value="3">3 — Bình thường</option><option value="2">2 — Cần cải thiện</option><option value="1">1 — Chưa hài lòng</option></select></label><label>Nội dung<textarea name="message" required minlength="10"></textarea></label>','feedback','Lưu góp ý')+'</div>'
    (folder/'feedback.html').write_text(page(c,'Góp ý',feedback,'feedback.html'),encoding='utf-8')
