    for file,title,fields,action,tail in [('register.html','Đăng ký',inp('Họ tên','name')+inp('Email','email','email')+inp('Mật khẩu (ít nhất 8 ký tự)','password','password','minlength="8" autocomplete="new-password"')+inp('Nhập lại mật khẩu','confirm','password'),'register','<a href="login.html">Đã có tài khoản? Đăng nhập</a>'),('login.html','Đăng nhập',inp('Email','email','email')+inp('Mật khẩu','password','password','autocomplete="current-password"'),'login','<a href="register.html">Tạo tài khoản</a>'),('change-password.html','Đổi mật khẩu',inp('Mật khẩu hiện tại','old','password')+inp('Mật khẩu mới','password','password','minlength="8"')+inp('Nhập lại mật khẩu mới','confirm','password'),'password','<a href="login.html">Đăng nhập</a>')]:
        (folder/file).write_text(page(c,title,f'<div class="narrow"><h1>{title}</h1>{authnotice}<div id="account"></div>'+form(fields,action,title)+f'<p>{tail}</p></div>','login.html'),encoding='utf-8')
    manage='<div class="narrow"><h1>Thêm nội dung</h1><p>Thêm sản phẩm, dịch vụ hoặc mục nội dung để cá nhân hóa bài làm. Dữ liệu chỉ lưu trên trình duyệt này.</p>'+form(inp('Tên nội dung','name','text','maxlength="100"')+inp('Giá / chi phí (VNĐ, 0 nếu miễn phí)','price','number','min="0" max="1000000000"')+'<label>Danh mục<select name="category"><option>Nổi bật</option><option>Bộ sưu tập</option></select></label><label>Mô tả<textarea name="description" required maxlength="2000"></textarea></label><label>Ảnh JPG / PNG / WebP (tối đa 1 MB)<input name="image" type="file" accept="image/jpeg,image/png,image/webp" required></label>','manage','Thêm nội dung')+'</div>'
